from collections import Counter

def exist(board: List[List[str]], word: str) -> bool:
    rows, cols = len(board), len(board[0])
    available = Counter(ch for row in board for ch in row)
    if any(available[ch] < need for ch, need in Counter(word).items()):
        return False

    def search(r: int, c: int, i: int) -> bool:
        if i == len(word):
            return True
        if not (0 <= r < rows and 0 <= c < cols) or board[r][c] != word[i]:
            return False
        board[r][c] = "#"
        found = (search(r + 1, c, i + 1) or search(r - 1, c, i + 1)
                 or search(r, c + 1, i + 1) or search(r, c - 1, i + 1))
        board[r][c] = word[i]
        return found

    return any(search(r, c, 0) for r in range(rows) for c in range(cols))
